// Parse RemoteOK API response
// RemoteOK returns an array where index 0 is metadata
const raw = $input.all();
const jobs = [];

for (const item of raw) {
  let data = item.json;
  // Handle array format (API returns array)
  if (Array.isArray(data)) {
    data = data.slice(1); // skip first metadata element
    for (const job of data) {
      if (!job || !job.id) continue;
      jobs.push({
        json: {
          job_id: 'remoteok-' + job.id,
          job_title: job.position || '',
          company: job.company || '',
          job_url: job.url || ('https://remoteok.com/remote-jobs/' + job.id),
          source: 'RemoteOK',
          location_text: job.location || 'Worldwide',
          salary: job.salary || '',
          description: (job.description || '') + ' ' + (job.tags || []).join(' '),
          posted_date: job.date || new Date().toISOString(),
          tags: (job.tags || []).join(', ')
        }
      });
    }
  } else if (data && data.position) {
    // Single job object
    jobs.push({
      json: {
        job_id: 'remoteok-' + (data.id || data.slug || Math.random()),
        job_title: data.position || '',
        company: data.company || '',
        job_url: data.url || '',
        source: 'RemoteOK',
        location_text: data.location || 'Worldwide',
        salary: data.salary || '',
        description: (data.description || '') + ' ' + (data.tags || []).join(' '),
        posted_date: data.date || new Date().toISOString(),
        tags: (data.tags || []).join(', ')
      }
    });
  }
}

return jobs.length > 0 ? jobs : [{ json: { _source: 'RemoteOK', _count: 0, _jobs: [] } }];

// Parse Remotive API response
const raw = $input.all();
const jobs = [];

for (const item of raw) {
  const data = item.json;
  const jobList = data.jobs || [];
  for (const job of jobList) {
    jobs.push({
      json: {
        job_id: 'remotive-' + job.id,
        job_title: job.title || '',
        company: job.company_name || '',
        job_url: job.url || '',
        source: 'Remotive',
        location_text: job.candidate_required_location || 'Worldwide',
        salary: job.salary || '',
        description: (job.description || '').replace(/<[^>]*>/g, ' '),
        posted_date: job.publication_date || new Date().toISOString(),
        tags: (job.tags || []).join(', ')
      }
    });
  }
}

return jobs.length > 0 ? jobs : [{ json: { _source: 'Remotive', _count: 0 } }];

// Parse WWR RSS (XML text → jobs)
// n8n passes raw text body from HTTP node
const raw = $input.all();
const jobs = [];

for (const item of raw) {
  const xml = item.json.data || item.json.body || '';
  if (!xml) continue;

  // Simple regex-based RSS parser
  const itemMatches = xml.match(/<item>([\s\S]*?)<\/item>/g) || [];

  for (const itemXml of itemMatches) {
    const getTag = (tag) => {
      const match = itemXml.match(new RegExp('<' + tag + '[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]></' + tag + '>|<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>'));
      return match ? (match[1] || match[2] || '').trim() : '';
    };

    const url = getTag('link') || getTag('guid');
    const title = getTag('title');
    if (!title || !url) continue;

    jobs.push({
      json: {
        job_id: 'wwr-' + Buffer.from(url).toString('base64').slice(0, 20),
        job_title: title,
        company: getTag('author') || getTag('dc:creator') || '',
        job_url: url,
        source: 'WeWorkRemotely',
        location_text: getTag('region') || 'Worldwide',
        salary: '',
        description: getTag('description').replace(/<[^>]*>/g, ' '),
        posted_date: getTag('pubDate') || new Date().toISOString(),
        tags: getTag('category') || ''
      }
    });
  }
}

return jobs.length > 0 ? jobs : [{ json: { _source: 'WWR', _count: 0 } }];

// Parse Himalayas RSS
const raw = $input.all();
const jobs = [];

for (const item of raw) {
  const xml = item.json.data || item.json.body || '';
  if (!xml) continue;

  const itemMatches = xml.match(/<item>([\s\S]*?)<\/item>/g) || [];

  for (const itemXml of itemMatches) {
    const getTag = (tag) => {
      const match = itemXml.match(new RegExp('<' + tag + '[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]></' + tag + '>|<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>'));
      return match ? (match[1] || match[2] || '').trim() : '';
    };

    const url = getTag('link') || getTag('guid');
    const title = getTag('title');
    if (!title || !url) continue;

    const desc = getTag('description').replace(/<[^>]*>/g, ' ');
    const company = getTag('author') || getTag('dc:creator') || url.match(/company\/([^/]+)/)?.[1] || '';

    jobs.push({
      json: {
        job_id: 'himalayas-' + Buffer.from(url).toString('base64').slice(0, 20),
        job_title: title,
        company: company,
        job_url: url,
        source: 'Himalayas',
        location_text: getTag('location') || 'Worldwide',
        salary: getTag('salary') || '',
        description: desc,
        posted_date: getTag('pubDate') || new Date().toISOString(),
        tags: getTag('category') || ''
      }
    });
  }
}

return jobs.length > 0 ? jobs : [{ json: { _source: 'Himalayas', _count: 0 } }];

