}

return jobs.length > 0 ? jobs : [{ json: { _source: 'Dynamite', _count: 0 } }];

// Parse Wellfound HTML/JSON scrape
// Wellfound loads jobs via JS so we do best-effort HTML extraction
const raw = $input.all();
const jobs = [];

for (const item of raw) {
  const html = item.json.data || item.json.body || '';
  if (!html) continue;

  // Try to extract JSON from script tags (Next.js __NEXT_DATA__)
  const nextDataMatch = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (nextDataMatch) {
    try {
      const nextData = JSON.parse(nextDataMatch[1]);
      const startups = nextData?.props?.pageProps?.startups || 
                       nextData?.props?.pageProps?.jobs || [];
      for (const s of startups) {
        const jobList = s.jobs || (s.job_title ? [s] : []);
        for (const job of jobList) {
          const slug = job.slug || job.id || '';
          jobs.push({
            json: {
              job_id: 'wellfound-' + slug,
              job_title: job.title || job.job_title || '',
              company: s.name || s.company || '',
              job_url: 'https://wellfound.com/jobs/' + slug,
              source: 'Wellfound',
              location_text: job.location_type || 'Remote',
              salary: (job.compensation || '') + '',
              description: job.description || '',
              posted_date: job.created_at || new Date().toISOString(),
              tags: (job.skills || []).join(', ')
            }
          });
        }
      }
    } catch(e) {
      // JSON parse failed, skip
    }
  }

  // Fallback: regex extract job cards from HTML
  if (jobs.length === 0) {
    const titleMatches = [...html.matchAll(/data-test="JobListing"[\s\S]*?<a[^>]+href="([^"]+)"[^>]*>([^<]+)<\/a>/g)];
    for (const m of titleMatches) {
      jobs.push({
        json: {
          job_id: 'wellfound-' + Buffer.from(m[1]).toString('base64').slice(0, 20),
          job_title: m[2].trim(),
          company: '',
          job_url: m[1].startsWith('http') ? m[1] : 'https://wellfound.com' + m[1],
          source: 'Wellfound',
          location_text: 'Remote',
          salary: '',
          description: '',
          posted_date: new Date().toISOString(),
          tags: ''
        }
      });
    }
  }
}

return jobs.length > 0 ? jobs : [{ json: { _source: 'Wellfound', _count: 0 } }];

// Parse YC Work at a Startup
const raw = $input.all();
const jobs = [];

for (const item of raw) {
  const html = item.json.data || item.json.body || '';
  if (!html) continue;

  // Try __NEXT_DATA__ or embedded JSON
  const nextDataMatch = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (nextDataMatch) {
    try {
      const nextData = JSON.parse(nextDataMatch[1]);
      const jobList = nextData?.props?.pageProps?.jobPostings ||
                      nextData?.props?.pageProps?.jobs || [];
      for (const job of jobList) {
        const id = job.id || job.external_id || '';
        jobs.push({
          json: {
            job_id: 'yc-' + id,
            job_title: job.title || '',
            company: job.company?.name || job.companyName || '',
            job_url: 'https://www.workatastartup.com/jobs/' + id,
            source: 'YCombinator',
            location_text: job.remote_legal_countries?.join(', ') || job.location || 'Worldwide',
            salary: job.min_experience ? '' : (job.salary_range || ''),
            description: job.description || '',
            posted_date: job.created_at || new Date().toISOString(),
            tags: (job.skills || job.tags || []).join(', ')
          }
        });
      }
    } catch(e) { /* skip */ }
  }
}

return jobs.length > 0 ? jobs : [{ json: { _source: 'YCombinator', _count: 0 } }];

// Parse Otta
const raw = $input.all();
const jobs = [];

for (const item of raw) {
  const data = item.json;
  // Try JSON response
  const jobList = data.jobs || data.results || data.data || [];
  if (Array.isArray(jobList)) {
    for (const job of jobList) {
      const id = job.id || job.slug || '';
      jobs.push({
        json: {
          job_id: 'otta-' + id,
          job_title: job.title || job.name || '',
          company: job.company?.name || job.employer || '',
          job_url: job.url || ('https://app.otta.com/jobs/' + id),
          source: 'Otta',
          location_text: job.remote ? 'Remote Worldwide' : (job.location || ''),
          salary: job.salary_min ? `${job.salary_min}-${job.salary_max}` : '',
          description: job.description || job.summary || '',
          posted_date: job.created_at || new Date().toISOString(),
          tags: (job.skills || []).map(s => s.value || s).join(', ')
        }
      });
    }
  } else {
    // HTML fallback - try extracting from body
    const html = data.body || data.data || '';
    if (typeof html === 'string') {
      const matches = [...html.matchAll(/"title":"([^"]+)","company":"([^"]+)".*?"url":"([^"]+)"/g)];
      for (const m of matches) {
        jobs.push({
          json: {
            job_id: 'otta-' + Buffer.from(m[3]).toString('base64').slice(0, 20),
            job_title: m[1],
            company: m[2],
            job_url: m[3],
            source: 'Otta',
            location_text: 'Remote',
            salary: '',
            description: '',
            posted_date: new Date().toISOString(),
            tags: ''
          }
        });
      }
    }
  }
}

return jobs.length > 0 ? jobs : [{ json: { _source: 'Otta', _count: 0 } }];

// Normalize: ensure all jobs have consistent fields and filter out empty results
const items = $input.all();
const normalized = [];

for (const item of items) {
  const j = item.json;

  // Skip placeholder items (from failed fetches)
  if (j._count === 0 || !j.job_title || !j.job_url) continue;

  // Clean and normalize
  const title = (j.job_title || '').trim();
  const company = (j.company || '').trim();
  const url = (j.job_url || '').trim();
  const desc = (j.description || '').trim();

  if (!title || !url) continue;

  // Build a stable job_id
  const job_id = j.job_id || j.source + '-' + Buffer.from(url).toString('base64').slice(0, 24);

  // Normalize posted_date to ISO
  let posted_date = j.posted_date || '';
  try { posted_date = new Date(posted_date).toISOString(); } catch(e) { posted_date = new Date().toISOString(); }

  normalized.push({
    json: {
      job_id,
      job_title: title,
      company,
      job_url: url,
      source: j.source || 'Unknown',
      location_text: (j.location_text || 'Worldwide').trim(),
      salary: (j.salary || '').trim(),
      description: desc,
      posted_date,
      tags: (j.tags || '').trim(),
      date_found: new Date().toISOString()
    }
  });
}

// Remove duplicates by job_url within this batch
const seen = new Set();
const deduped = normalized.filter(item => {
  if (seen.has(item.json.job_url)) return false;
  seen.add(item.json.job_url);
  return true;
});

return deduped;

// Deduplicate against existing Google Sheets data + apply hard Taiwan filter

// Get new jobs from previous node
const newJobs = $('Normalize Jobs').all().map(i => i.json);

// Get existing jobs from Google Sheets
const existingRows = $('Read Existing Jobs').all().map(i => i.json);
const existingUrls = new Set(existingRows.map(r => r.job_url).filter(Boolean));
const existingKeys = new Set(
  existingRows.map(r => ((r.company || '') + '|' + (r.job_title || '')).toLowerCase())
);

// Hard filter: reject if any of these phrases appear in location_text or description
const REJECT_PATTERNS = [
  /\bus only\b/i, /\bus-only\b/i,
  /\bcanada only\b/i, /\buk only\b/i,
  /\beu only\b/i, /\beurope only\b/i,
  /\baustralia only\b/i,
  /\bmust be based in\b/i,
  /\bmust live in\b/i,
  /\bmust be authorized to work in\b/i,
  /\blocal work permit required\b/i,
  /\bhybrid\b/i,
  /\bonsite\b/i,
  /\bon-site\b/i,
  /\boffice required\b/i,
  /\bremote within (the )?(us|uk|eu|canada|australia|germany|france)\b/i,
  /\bfixed (us|est|pst|cet|eu) hours\b/i,
  /\bauthorized to work in the (us|uk|eu|canada|australia)\b/i,
  /\bwork authorization (required|needed) in\b/i,
  /\bwork permit required\b/i,
  /\bonly (accepting|considering) (applicants|candidates) (from|based in|located in) (us|uk|eu|canada|australia|united states|united kingdom)\b/i
];

// Keep patterns: any of these signals increase likelihood of Taiwan eligibility
const KEEP_PATTERNS = [
  /worldwide remote/i, /global remote/i, /work from anywhere/i, /anywhere/i,
  /apac remote/i, /international contractors?/i, /contractor role/i,
  /b2b contractor/i, /hires via deel/i, /hires via remote\.com/i,
  /hires via oyster/i, /eor supported/i, /employer of record/i,
  /remote[ -]first/i, /distributed team/i, /no timezone requirement/i
];

const results = [];
const rejected = [];

for (const job of newJobs) {
  // Dedup check
  if (existingUrls.has(job.job_url)) {
    rejected.push({ ...job, reject_reason: 'duplicate_url' });
    continue;
  }
  const companyTitleKey = (job.company + '|' + job.job_title).toLowerCase();
  if (existingKeys.has(companyTitleKey)) {
    rejected.push({ ...job, reject_reason: 'duplicate_company_title' });
    continue;
  }

  const searchText = (job.location_text + ' ' + job.description + ' ' + job.tags).toLowerCase();

  // Hard reject
  let hardRejected = false;
  let hardRejectReason = '';
  for (const pattern of REJECT_PATTERNS) {
    if (pattern.test(searchText)) {
      hardRejected = true;
      hardRejectReason = 'hard_filter: ' + pattern.toString();
      break;
    }
  }

  if (hardRejected) {
    rejected.push({ ...job, reject_reason: hardRejectReason });
    continue;
  }

  // Check for keep signals
  let hasKeepSignal = false;
  for (const pattern of KEEP_PATTERNS) {
    if (pattern.test(searchText)) {
      hasKeepSignal = true;
      break;
    }
  }

  results.push({ ...job, has_keep_signal: hasKeepSignal, reject_reason: '' });
}

// Store rejected for later output
$execution.customData = $execution.customData || {};
$execution.customData.hardRejected = rejected;

return results.map(j => ({ json: j }));

// Parse AI response and merge back with job data
const aiResponse = $input.first().json;
const jobData = $('Process One Job at a Time').first().json;

// Extract text from Anthropic response
let aiText = '';
try {
  aiText = aiResponse.content?.[0]?.text || aiResponse.choices?.[0]?.message?.content || '';
} catch(e) { aiText = ''; }

// Parse the JSON from AI response
let aiResult = {
  taiwan_eligible: 'unclear',
  reason: 'AI parse error',
  location_risk: 'medium',
  timezone_risk: 'medium',
  contractor_possible: 'unclear',
  decision: 'manual_check'
};

try {
  // Extract JSON from text (AI might wrap it in ```json)
  const jsonMatch = aiText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiResult = JSON.parse(jsonMatch[0]);
  }
} catch(e) { /* use defaults */ }

// Determine async level from description
const desc = (jobData.description + ' ' + jobData.tags).toLowerCase();
const asyncSignals = [
  { pattern: /\basync\b|\basynchronous\b|\bno meetings\b|\blow meeting culture\b/, level: 'high', points: 25 },
  { pattern: /\bflexible hours\b|\bflexible schedule\b|\bwork across time zones\b/, level: 'high', points: 20 },
  { pattern: /\bdistributed team\b|\bfully remote\b|\bremote[- ]first\b/, level: 'medium', points: 15 },
  { pattern: /\bremote\b/, level: 'low', points: 10 }
];

const asyncRejectPatterns = [
  /\bstrict 9[- ]to[- ]5\b|\bfixed (us|est|pst|cet) hours\b/i,
  /\bdaily live calls required\b/i,
  /\bmust overlap full business day\b/i,
  /\b(synchronous|sync) team\b/i
];

let asyncLevel = 'unknown';
let asyncPoints = 0;
let asyncRejected = false;

for (const r of asyncRejectPatterns) {
  if (r.test(desc)) { asyncRejected = true; break; }
}

if (!asyncRejected) {
  for (const sig of asyncSignals) {
    if (sig.pattern.test(desc)) {
      asyncLevel = sig.level;
      asyncPoints = sig.points;
      break;
    }
  }
}

// Role fit scoring
const rolePatterns = [
  { pattern: /data (scientist|analyst|science)|machine learning|ml engineer|ai (specialist|analyst)|marketing analyst|growth analyst|bi analyst|business intelligence|martech|marketing data|performance marketing|automation specialist|ai workflow|ai marketing|creative strategist.*data|customer analytics|product analyst/, points: 25, category: 'core_fit' },
  { pattern: /data engineer|analytics engineer|sql|python|tableau|power bi|seo|ppc|paid (search|social|media)|digital marketing|marketing ops|revenue ops|sales ops/, points: 15, category: 'adjacent_fit' },
  { pattern: /software engineer|frontend|backend|devops|designer|ux|ui/, points: 5, category: 'low_fit' }
];

let rolePoints = 0;
let roleCategory = 'no_match';
const titleDesc = (jobData.job_title + ' ' + desc).toLowerCase();

for (const rp of rolePatterns) {
  if (rp.pattern.test(titleDesc)) {
    rolePoints = rp.points;
    roleCategory = rp.category;
    break;
  }
}

// Taiwan eligibility points
let taiwanPoints = 0;
const eligible = aiResult.taiwan_eligible;
const locRisk = aiResult.location_risk;
if (eligible === 'yes' && locRisk === 'low') taiwanPoints = 40;
else if (eligible === 'yes' && locRisk === 'medium') taiwanPoints = 30;
else if (eligible === 'unclear' && locRisk !== 'high') taiwanPoints = 20;
else if (eligible === 'yes' && locRisk === 'high') taiwanPoints = 20;
else taiwanPoints = 0;

// Check for APAC bonus
if (/apac/i.test(jobData.location_text + desc)) taiwanPoints = Math.max(taiwanPoints, 30);

// Salary scoring
let salaryPoints = 0;
const salary = jobData.salary || '';
const salaryNums = salary.match(/\d+[,.]?\d*/g);
if (salaryNums && salaryNums.length > 0) {
  const salaryVal = parseFloat(salaryNums[0].replace(',', ''));
  const isAnnual = salary.toLowerCase().includes('/yr') || salary.toLowerCase().includes('/year') || salary.toLowerCase().includes('annual') || salaryVal > 50000;
  const monthly = isAnnual ? salaryVal / 12 : salaryVal;
  if (monthly >= 5000) salaryPoints = 25;
  else if (monthly >= 3000) salaryPoints = 15;
  else salaryPoints = 10;
} else if (salary) {
  salaryPoints = 10; // has some salary info
}

// Total score
const score = taiwanPoints + asyncPoints + rolePoints + salaryPoints;

// Final decision
let finalDecision = 'reject';
if (asyncRejected || aiResult.decision === 'reject' || aiResult.taiwan_eligible === 'no') {
  finalDecision = 'reject';
} else if (score >= 85 && aiResult.taiwan_eligible !== 'no') {
  finalDecision = 'apply_immediately';
} else if (score >= 70) {
  finalDecision = aiResult.taiwan_eligible === 'unclear' ? 'manual_check' : 'keep';
} else {
  finalDecision = 'reject';
}

// Build why_good_fit summary
const whyFit = [
  aiResult.taiwan_eligible === 'yes' ? '✓ Taiwan eligible' : '',
  asyncLevel === 'high' ? '✓ Fully async' : asyncLevel === 'medium' ? '✓ Flexible hours' : '',
  roleCategory === 'core_fit' ? '✓ Core role match' : roleCategory === 'adjacent_fit' ? '✓ Adjacent role' : '',
  salaryPoints >= 15 ? '✓ Good salary' : ''
].filter(Boolean).join(' | ');

return [{
  json: {
    ...jobData,
    taiwan_eligible: aiResult.taiwan_eligible,
    taiwan_reason: aiResult.reason,
    location_risk: aiResult.location_risk,
    timezone_risk: aiResult.timezone_risk,
    contractor_possible: aiResult.contractor_possible,
    ai_decision: aiResult.decision,
    async_level: asyncRejected ? 'rejected' : (asyncLevel || 'unknown'),
    async_points: asyncPoints,
    role_category: roleCategory,
    role_points: rolePoints,
    taiwan_points: taiwanPoints,
    salary_points: salaryPoints,
    score,
    final_decision: finalDecision,
    why_good_fit: whyFit,
    application_status: 'new',
    notes: ''
  }
}];

// Build the daily digest from all processed jobs
const items = $input.all().map(i => i.json);

// Separate by decision
const topJobs = items
  .filter(j => j.score >= 70 && j.taiwan_eligible !== 'no' && j.job_title)
  .sort((a, b) => b.score - a.score)
  .slice(0, 10);

const manualCheck = items
  .filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70 && j.job_title)
  .sort((a, b) => b.score - a.score);

const rejected = items.filter(j => j.taiwan_eligible === 'no' || j.score < 70 || j.final_decision === 'reject');

// Count rejection reasons
const rejectedUSOnly = rejected.filter(j => /us only|united states only/i.test(j.taiwan_reason || '')).length;
const rejectedEUOnly = rejected.filter(j => /eu only|europe only|uk only/i.test(j.taiwan_reason || '')).length;
const rejectedHybrid = rejected.filter(j => /hybrid|onsite/i.test(j.taiwan_reason || '')).length;
const rejectedTimezone = rejected.filter(j => j.timezone_risk === 'high').length;

// Build digest text
let digest = `📋 <b>Daily Taiwan Eligible Async Remote Jobs — ${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei' })}</b>\n\n`;

if (topJobs.length === 0) {
  digest += `<i>No qualifying jobs found today. The filter is working — better to wait for the right one.</i>\n\n`;
} else {
  digest += `<b>🎯 Top Jobs Today (${topJobs.length} found)</b>\n\n`;

  topJobs.forEach((job, idx) => {
    const urgencyIcon = job.score >= 85 ? '🚀' : job.score >= 75 ? '⭐' : '📌';
    digest += `${idx + 1}. ${urgencyIcon} <b>${job.job_title}</b>\n`;
    digest += `   Company: ${job.company}\n`;
    digest += `   Score: ${job.score}/100${job.score >= 85 ? ' — APPLY NOW' : ''}\n`;
    digest += `   Taiwan eligible: ${job.taiwan_eligible} — ${job.taiwan_reason}\n`;
    digest += `   Async level: ${job.async_level}\n`;
    digest += `   Timezone risk: ${job.timezone_risk}\n`;
    digest += `   Salary: ${job.salary || 'Not listed'}\n`;
    digest += `   Why it fits Jerry: ${job.why_good_fit}\n`;
    digest += `   Apply: ${job.job_url}\n\n`;
  });
}

if (manualCheck.length > 0) {
  digest += `\n⚠️ <b>Manual Check Needed (${manualCheck.length} jobs — Taiwan unclear but score high)</b>\n`;
  manualCheck.slice(0, 5).forEach(job => {
    digest += `• ${job.job_title} at ${job.company} (Score: ${job.score}) — ${job.taiwan_reason}\n`;
    digest += `  ${job.job_url}\n`;
  });
}

digest += `\n\n📊 <b>Rejection Summary</b>\n`;
digest += `• US only: ${rejectedUSOnly}\n`;
digest += `• EU/UK only: ${rejectedEUOnly}\n`;
digest += `• Hybrid/Onsite: ${rejectedHybrid}\n`;
digest += `• Timezone risk: ${rejectedTimezone}\n`;
digest += `• Total rejected/skipped: ${rejected.length}\n`;

digest += `\n\n<i>One-sentence rule: I can do this job while living in Taiwan, without moving, without foreign work authorization, and without destroying my sleep schedule.</i>`;

return [{ json: { digest_html: digest, total_qualified: topJobs.length, total_rejected: rejected.length, top_score: topJobs[0]?.score || 0, date: new Date().toISOString() } }];
